type Config struct {                 // state lives in the value, not the package
    mu    sync.Mutex
    level int
}

func NewConfig() *Config         { return &Config{level: 1} }
func (c *Config) SetLevel(l int) { c.mu.Lock(); defer c.mu.Unlock(); c.level = l }
func (c *Config) Level() int     { c.mu.Lock(); defer c.mu.Unlock(); return c.level }

